"use client";

import { useEffect, useMemo, useState } from "react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { apiFetch } from "@/lib/api";

type Employee = { id: string; fullName: string; employeeNumber?: string | null; userId?: string | null };
type User = { id: string; email: string; fullName: string; role: string; status: string; lastLoginAt?: string | null; employees?: Employee[] };
type Form = { id: string; fullName: string; email: string; role: string; password: string; employeeId: string };
const emptyForm: Form = { id: "", fullName: "", email: "", role: "EMPLOYEE", password: "", employeeId: "" };
const roles = ["ORGANISATION_ADMIN", "FINANCE_MANAGER", "HR_MANAGER", "SALES_MANAGER", "PROJECT_MANAGER", "IT_MANAGER", "ACCOUNTANT", "EMPLOYEE", "VIEWER"];
const generatePassword = () => { const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"; return Array.from({ length: 6 }, () => chars[Math.floor(Math.random() * chars.length)]).join(""); };

export default function TeamPage() {
  const [users, setUsers] = useState<User[]>([]); const [employees, setEmployees] = useState<Employee[]>([]); const [form, setForm] = useState<Form>(emptyForm); const [showForm, setShowForm] = useState(false); const [selected, setSelected] = useState<User | null>(null); const [search, setSearch] = useState(""); const [error, setError] = useState(""); const [message, setMessage] = useState("");
  const load = async () => { try { const [userData, employeeData] = await Promise.all([apiFetch<{ items: User[] }>("/users"), apiFetch<{ items: Employee[] }>("/hr/employees")]); setUsers(userData.items); setEmployees(employeeData.items); setError(""); } catch (e) { setError(e instanceof Error ? e.message : "Unable to load team access."); } };
  useEffect(() => { void load(); }, []);
  const filtered = useMemo(() => users.filter((user) => `${user.fullName} ${user.email} ${user.role} ${user.employees?.[0]?.fullName || ""}`.toLowerCase().includes(search.toLowerCase())), [users, search]);
  const update = (key: keyof Form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const openCreate = () => { setForm({ ...emptyForm, password: generatePassword() }); setShowForm(true); setError(""); };
  const openEdit = (user: User) => { setForm({ id: user.id, fullName: user.fullName, email: user.email, role: user.role, password: "", employeeId: user.employees?.[0]?.id || "" }); setShowForm(true); setError(""); };
  const save = async () => { try { if (!form.fullName.trim() || !form.email.trim()) throw new Error("Full name and email are required."); if (!form.id && form.password.length !== 6) throw new Error("The generated password must be exactly 6 characters."); await apiFetch(form.id ? `/settings/team/${form.id}` : "/settings/team", { method: form.id ? "PATCH" : "POST", body: JSON.stringify({ fullName: form.fullName.trim(), email: form.email.trim(), role: form.role, employeeId: form.employeeId || null, ...(form.password ? { password: form.password } : {}) }) }); setMessage(form.id ? "User updated and employee link saved." : `User created. Temporary password: ${form.password}`); setForm(emptyForm); setShowForm(false); await load(); } catch (e) { setError(e instanceof Error ? e.message : "Unable to save user."); } };
  const resetPassword = async (user: User) => { const password = generatePassword(); try { await apiFetch(`/settings/team/${user.id}`, { method: "PATCH", body: JSON.stringify({ password }) }); setMessage(`Password reset for ${user.fullName}. Temporary password: ${password}`); await load(); } catch (e) { setError(e instanceof Error ? e.message : "Unable to reset password."); } };
  const setStatus = async (user: User) => { try { await apiFetch(`/users/${user.id}/status`, { method: "PATCH", body: JSON.stringify({ status: user.status === "ACTIVE" ? "INACTIVE" : "ACTIVE" }) }); await load(); } catch (e) { setError(e instanceof Error ? e.message : "Unable to update status."); } };
  const remove = async (user: User) => { if (!window.confirm(`Remove ${user.fullName} from this workspace?`)) return; try { await apiFetch(`/settings/team/${user.id}`, { method: "DELETE" }); setMessage("User removed."); await load(); } catch (e) { setError(e instanceof Error ? e.message : "Unable to remove user."); } };
  const availableEmployees = employees.filter((employee) => !employee.userId || employee.id === form.employeeId);

  return <AppShell title="Team Access" description="Manage login accounts, employee links, roles, and account status."><section className="space-y-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-brand-500">Users and permissions</p><h1 className="mt-2 text-3xl font-semibold text-ink">Team access</h1><p className="mt-2 text-sm text-slate-500">Connect each login to an employee profile for HR, payroll, and attendance access.</p></div><button onClick={openCreate} className="rounded-2xl bg-brand-500 px-4 py-2.5 text-sm font-semibold text-white">Add user</button></div>{error && <p className="rounded-2xl bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}{message && <p className="rounded-2xl bg-emerald-50 p-3 text-sm text-emerald-700">{message}</p>}<Card className="overflow-hidden"><div className="border-b border-line bg-slate-50/70 p-4"><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search name, email, role, or employee" className="w-full max-w-lg rounded-2xl border border-line px-4 py-3 text-sm" /></div><div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-soft"><tr><th className="p-4">User</th><th className="p-4">Linked employee</th><th className="p-4">Role</th><th className="p-4">Status</th><th className="p-4">Last login</th><th className="p-4 text-right">Actions</th></tr></thead><tbody>{filtered.map((user) => <tr key={user.id} onClick={() => setSelected(user)} className="cursor-pointer border-t border-line transition hover:bg-soft/40"><td className="p-4"><p className="font-semibold text-ink">{user.fullName}</p><p className="mt-1 text-xs text-slate-500">{user.email}</p></td><td className="p-4 text-slate-600">{user.employees?.[0]?.fullName || "Not linked"}</td><td className="p-4 text-slate-600">{user.role}</td><td className="p-4"><span className="rounded-full bg-soft px-2.5 py-1 text-xs font-semibold">{user.status}</span></td><td className="p-4 text-slate-500">{user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleDateString() : "Never"}</td><td className="p-4"><div className="flex flex-wrap justify-end gap-2"><button onClick={(e) => { e.stopPropagation(); openEdit(user); }} className="rounded-xl border border-line px-3 py-1.5 text-xs font-semibold">Edit</button><button onClick={(e) => { e.stopPropagation(); void resetPassword(user); }} className="rounded-xl border border-amber-200 px-3 py-1.5 text-xs font-semibold text-amber-700">Reset password</button><button onClick={(e) => { e.stopPropagation(); void setStatus(user); }} className="rounded-xl border border-line px-3 py-1.5 text-xs font-semibold">{user.status === "ACTIVE" ? "Deactivate" : "Activate"}</button><button onClick={(e) => { e.stopPropagation(); void remove(user); }} className="rounded-xl border border-rose-200 px-3 py-1.5 text-xs font-semibold text-rose-600">Remove</button></div></td></tr>)}{!filtered.length && <tr><td colSpan={6} className="p-8 text-center text-slate-500">No users found.</td></tr>}</tbody></table></div></Card>
      {showForm && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/35 p-4" onClick={() => setShowForm(false)}><Card className="w-full max-w-2xl p-6" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between"><div><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-500">{form.id ? "Edit account" : "Create account"}</p><h2 className="mt-1 text-2xl font-semibold text-ink">Login and employee access</h2></div><button onClick={() => setShowForm(false)} className="rounded-xl border border-line px-3 py-2 text-sm">Close</button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><label className="text-xs font-semibold text-slate-500">Full name<input value={form.fullName} onChange={(e) => update("fullName", e.target.value)} className="mt-1 w-full rounded-2xl border border-line px-4 py-3 text-sm" placeholder="Full name" /></label><label className="text-xs font-semibold text-slate-500">Login email<input type="email" value={form.email} onChange={(e) => update("email", e.target.value)} className="mt-1 w-full rounded-2xl border border-line px-4 py-3 text-sm" placeholder="name@company.com" /></label><label className="text-xs font-semibold text-slate-500">Access role<select value={form.role} onChange={(e) => update("role", e.target.value)} className="mt-1 w-full rounded-2xl border border-line bg-white px-4 py-3 text-sm">{roles.map((role) => <option key={role}>{role}</option>)}</select></label><label className="text-xs font-semibold text-slate-500">Link employee<select value={form.employeeId} onChange={(e) => update("employeeId", e.target.value)} className="mt-1 w-full rounded-2xl border border-line bg-white px-4 py-3 text-sm"><option value="">No employee link</option>{availableEmployees.map((employee) => <option key={employee.id} value={employee.id}>{employee.fullName}{employee.employeeNumber ? ` · ${employee.employeeNumber}` : ""}</option>)}</select></label><label className="text-xs font-semibold text-slate-500 md:col-span-2">{form.id ? "New password (optional)" : "Generated temporary password"}<div className="mt-1 flex gap-2"><input type="text" readOnly={!form.id} value={form.password} onChange={(e) => update("password", e.target.value)} className="w-full rounded-2xl border border-line px-4 py-3 text-sm" placeholder="Six characters" />{!form.id && <button type="button" onClick={() => update("password", generatePassword())} className="rounded-2xl border border-line px-3 text-xs font-semibold">Regenerate</button>}</div></label></div><p className="mt-4 rounded-2xl bg-amber-50 p-3 text-xs text-amber-800">The temporary password is shown once after creation or reset. Ask the user to change it after signing in.</p><div className="mt-5 flex justify-end"><button onClick={() => void save()} className="rounded-2xl bg-brand-500 px-5 py-2.5 text-sm font-semibold text-white">{form.id ? "Save changes" : "Create login"}</button></div></Card></div>}
      {selected && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/35 p-4" onClick={() => setSelected(null)}><Card className="w-full max-w-xl p-6" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between"><div><p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-500">User profile</p><h2 className="mt-1 text-2xl font-semibold text-ink">{selected.fullName}</h2></div><button onClick={() => setSelected(null)} className="rounded-xl border border-line px-3 py-2 text-sm">Close</button></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-soft/50 p-3"><p className="text-xs text-slate-500">Login email</p><p className="mt-1 font-semibold">{selected.email}</p></div><div className="rounded-2xl bg-soft/50 p-3"><p className="text-xs text-slate-500">Linked employee</p><p className="mt-1 font-semibold">{selected.employees?.[0]?.fullName || "Not linked"}</p></div><div className="rounded-2xl bg-soft/50 p-3"><p className="text-xs text-slate-500">Role and status</p><p className="mt-1 font-semibold">{selected.role} · {selected.status}</p></div><div className="rounded-2xl bg-soft/50 p-3"><p className="text-xs text-slate-500">Last login</p><p className="mt-1 font-semibold">{selected.lastLoginAt ? new Date(selected.lastLoginAt).toLocaleString() : "Never"}</p></div></div></Card></div>}
    </section></AppShell>;
}
